def transform(grid):
    """Remove small speckle components, correcting them from adjacent large shapes."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    keep = [[False] * w for _ in range(h)]

    # A color component of at least four cells belongs to a real object; smaller
    # non-background components are noise. Keep the original shape of each object.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and not seen[yy][xx]
                            and grid[yy][xx] == color):
                        seen[yy][xx] = True
                        q.append((yy, xx))
            if len(cells) >= 4:
                for y, x in cells:
                    keep[y][x] = True

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or keep[r][c]:
                continue
            adjacent = Counter()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                y, x = r + dy, c + dx
                if 0 <= y < h and 0 <= x < w:
                    if grid[y][x] == bg or keep[y][x]:
                        adjacent[grid[y][x]] += 1
            # Only repair when there is a local majority; ties and isolated specks
            # revert to the dominant background color.
            non_bg = {color: n for color, n in adjacent.items() if color != bg}
            if non_bg:
                color, n = max(non_bg.items(), key=lambda item: item[1])
                if n > adjacent.get(bg, 0):
                    out[r][c] = color
                else:
                    out[r][c] = bg
            else:
                out[r][c] = bg
    return out
